package org.xingmu.tv;
import android.app.Activity;import android.content.*;import android.os.Build;import android.net.Uri;import java.io.*;import java.util.*;import java.util.concurrent.*;import androidx.media3.database.*;import androidx.media3.datasource.*;import androidx.media3.datasource.cache.*;import androidx.media3.exoplayer.offline.*;import androidx.media3.exoplayer.scheduler.Requirements;
@androidx.annotation.OptIn(markerClass=androidx.media3.common.util.UnstableApi.class)
final class OfflineStore {
 private static SimpleCache cache;private static DownloadManager manager;private static final ExecutorService network=Executors.newFixedThreadPool(3),preparation=Executors.newSingleThreadExecutor();
 static synchronized DownloadManager manager(Context c){if(manager==null){Context app=c.getApplicationContext();StandaloneDatabaseProvider database=new StandaloneDatabaseProvider(app);cache=new SimpleCache(new File(app.getFilesDir(),"offline-media"),new NoOpCacheEvictor(),database);manager=new DownloadManager(app,new DefaultDownloadIndex(database,"offline"),request->{CatalogItem item=OfflineMetadata.decode(request.id,request.uri.toString(),request.data);CacheDataSource.Factory factory=new CacheDataSource.Factory().setCache(cache).setUpstreamDataSourceFactory(new DefaultHttpDataSource.Factory().setUserAgent(item.userAgent).setAllowCrossProtocolRedirects(true).setConnectTimeoutMs(8000).setReadTimeoutMs(15000));return new VerifiedDownloader(new DefaultDownloaderFactory(factory,network).createDownloader(request));});manager.setMaxParallelDownloads(2);manager.setRequirements(new Requirements(Requirements.NETWORK|Requirements.DEVICE_STORAGE_NOT_LOW));}return manager;}
 static DataSource.Factory playback(Context c){manager(c);return new CacheDataSource.Factory().setCache(cache).setUpstreamDataSourceFactory(null).setCacheWriteDataSinkFactory(null);}
 static Download completed(Context c,String id)throws IOException{Download download=manager(c).getDownloadIndex().getDownload(id);if(download==null||download.state!=Download.STATE_COMPLETED||!usable(download))throw new IOException("视频尚未下载完成");return download;}
 static List<Download> list(Context c)throws IOException{List<Download> downloads=new ArrayList<>();try(DownloadCursor cursor=manager(c).getDownloadIndex().getDownloads()){while(cursor.moveToNext())downloads.add(cursor.getDownload());}Collections.sort(downloads,(a,b)->Long.compare(b.startTimeMs,a.startTimeMs));return downloads;}
 static boolean usable(Download download){return download.getBytesDownloaded()>0&&OfflineMetadata.validated(download.request.data);}
 static CatalogItem item(Download download){return OfflineMetadata.decode(download.request.id,download.request.uri.toString(),download.request.data);}
 static void enqueue(Activity activity,CatalogItem item){enqueue(activity,item,item.url);}
 static void enqueue(Activity activity,CatalogItem item,String address){if(item.live()||!item.mode.equals("stream")||!CatalogParser.safeMediaUrl(address)){TvUi.toast(activity,"仅支持下载有直接播放地址的点播视频");return;}if(Build.VERSION.SDK_INT>=33&&activity.checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)activity.requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},12);TvUi.toast(activity,"正在准备下载…");preparation.execute(()->{try{Download existing=manager(activity).getDownloadIndex().getDownload(item.id);if(existing!=null&&existing.state!=Download.STATE_FAILED&&(existing.state!=Download.STATE_COMPLETED||usable(existing))){activity.runOnUiThread(()->{if(!activity.isDestroyed())TvUi.toast(activity,existing.state==Download.STATE_COMPLETED?"视频已下载，可在下载中心播放":"已在下载中心，无需重复添加");});return;}MediaFormat.Resolved resolved=null;Exception failure=null;LinkedHashSet<String> candidates=new LinkedHashSet<>();candidates.add(address);candidates.addAll(item.urls);for(String candidate:candidates){try{resolved=MediaFormat.resolveDownload(candidate,item.userAgent);break;}catch(Exception e){failure=e;}}if(resolved==null)throw new IOException("所有下载线路不可用："+(failure==null?"无地址":failure.getMessage()));DownloadRequest request=new DownloadRequest.Builder(item.id,Uri.parse(resolved.url)).setMimeType(resolved.mime).setData(OfflineMetadata.encode(item)).build();activity.runOnUiThread(()->{if(activity.isDestroyed())return;try{if(existing!=null&&existing.state==Download.STATE_COMPLETED)DownloadService.sendRemoveDownload(activity,OfflineDownloadService.class,item.id,true);DownloadService.sendAddDownload(activity,OfflineDownloadService.class,request,true);DownloadService.sendResumeDownloads(activity,OfflineDownloadService.class,true);TvUi.toast(activity,"已加入下载中心");}catch(RuntimeException e){TvUi.toast(activity,"无法启动下载："+e.getMessage());}});}catch(Exception e){activity.runOnUiThread(()->{if(!activity.isDestroyed())TvUi.toast(activity,"下载准备失败："+e.getMessage());});}});}
 static void retry(Activity c,Download download){enqueue(c,item(download));}
}
